package com.singtel.apigateway;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.client.RestClient;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.util.concurrent.*;import com.singtel.platformcommon.DomainError;
@RestController public class Gateway{private final RestClient client;private final Map<String,String> routes;private final ConcurrentHashMap<String,Bucket> buckets=new ConcurrentHashMap<>();private static class Bucket{long minute;int count;Bucket(long m){minute=m;}}
 public Gateway(RestClient c,@Value("${platform.promotion-url}")String p,@Value("${platform.rule-url}")String r,@Value("${platform.customer-url}")String u,@Value("${platform.eligibility-url}")String e,@Value("${platform.redemption-url}")String d){client=c;routes=Map.of("promotions",p,"rules",r,"customers",u,"eligibility",e,"redemptions",d);}
 @RequestMapping("/api/v1/**")public ResponseEntity<byte[]> proxy(HttpServletRequest req,@RequestBody(required=false)byte[] body){if(body!=null&&body.length>65536)throw new DomainError(HttpStatus.PAYLOAD_TOO_LARGE,"REQUEST_TOO_LARGE","Maximum request size is 64KB");String who=req.getUserPrincipal()==null?req.getRemoteAddr():req.getUserPrincipal().getName();long minute=System.currentTimeMillis()/60000;if(buckets.size()>10000)buckets.entrySet().removeIf(e->e.getValue().minute<minute);var b=buckets.computeIfAbsent(who,k->new Bucket(minute));synchronized(b){if(b.minute!=minute){b.minute=minute;b.count=0;}if(++b.count>120)throw new DomainError(HttpStatus.TOO_MANY_REQUESTS,"RATE_LIMITED","Maximum 120 requests per minute");}String[] parts=req.getRequestURI().split("/");if(parts.length<4||!routes.containsKey(parts[3]))throw DomainError.missing();String route=parts[3];if(route.equals("customers")&&req.getRequestURI().endsWith("/eligible-promotions"))route="eligibility";String target=routes.get(route)+req.getRequestURI()+(req.getQueryString()==null?"":"?"+req.getQueryString());var outbound=client.method(HttpMethod.valueOf(req.getMethod())).uri(target).header("X-Correlation-ID",String.valueOf(req.getAttribute("correlationId")));for(String h:List.of("Authorization","Idempotency-Key","X-Demo-Role")){if(req.getHeader(h)!=null)outbound.header(h,req.getHeader(h));}if(body!=null)outbound.contentType(MediaType.APPLICATION_JSON).body(body);return outbound.exchange((request,response)->{HttpHeaders headers=new HttpHeaders();if(response.getHeaders().getContentType()!=null)headers.setContentType(response.getHeaders().getContentType());headers.set("X-Correlation-ID",String.valueOf(req.getAttribute("correlationId")));return new ResponseEntity<>(response.getBody().readAllBytes(),headers,response.getStatusCode());});}
}
